use clap::{Parser, Subcommand};
use std::path::PathBuf;

mod config;
mod backend;
mod theme;
mod cli;
mod app;
mod models;

use config::Config;

#[derive(Parser)]
#[command(name = "executable")]
#[command(about = "Tui app allows writing and managing journals/notes from within the terminal With different local back-ends", long_about = None)]
#[command(version = "0.16.1")]
struct Args {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Sets the entries Json file path and starts using it
    #[arg(short = 'j', long)]
    json_file_path: Option<PathBuf>,

    /// Sets the entries sqlite file path and starts using it
    #[arg(short = 's', long)]
    sqlite_file_path: Option<PathBuf>,

    /// Sets the backend type and starts using it
    #[arg(short = 'b', long, value_parser = ["json", "sqlite"])]
    backend_type: Option<String>,

    /// Specifies the path for the configuration directory.
    /// Configuration files is considered as root for themes file too.
    /// It still accepts the path for configuration file for backward compatibility.
    #[arg(short = 'c', long, value_name = "DIR PATH")]
    config: Option<PathBuf>,

    /// Increases logging verbosity each use for up to 3 times
    #[arg(short = 'v', long, action = clap::ArgAction::Count)]
    verbose: u8,

    /// Specifies a file to use for logging
    #[arg(short = 'l', long, value_name = "FILE PATH")]
    log: Option<PathBuf>,
}

#[derive(Subcommand)]
enum Commands {
    /// Print the current settings including the paths for the back-end files
    #[command(visible_alias = "pc")]
    PrintConfig,

    /// Import journals from the given transfer JSON file to the current back-end file
    #[command(visible_alias = "imj")]
    ImportJournals {
        /// Path of the JSON file to import from
        #[arg(short = 'p', long, value_name = "FILE PATH")]
        path: PathBuf,
    },

    /// Assign priority for all the entries with empty priority field
    #[command(visible_alias = "ap")]
    AssignPriority {
        /// Priority value (Positive number)
        priority: u32,
    },

    /// Provides commands regarding changing themes and styles of the app
    #[command(visible_alias = "style")]
    Theme {
        #[command(subcommand)]
        command: ThemeCommands,
    },
}

#[derive(Subcommand)]
enum ThemeCommands {
    /// Prints the path to the user themes file
    #[command(visible_alias = "path")]
    PrintPath,

    /// Dumps the styles with the default values to be used as a reference and base for user custom themes
    #[command(visible_alias = "default")]
    PrintDefault,

    /// Creates user custom themes file if doesn't exist then writes the default styles to it
    #[command(visible_alias = "write")]
    WriteDefaults,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    // Load or create configuration
    let mut config = Config::load(&args.config)?;

    // Apply command-line overrides
    if let Some(json_path) = args.json_file_path {
        config.json_backend.file_path = json_path;
        config.backend_type = "json".to_string();
    }
    if let Some(sqlite_path) = args.sqlite_file_path {
        config.sqlite_backend.file_path = sqlite_path;
        config.backend_type = "sqlite".to_string();
    }
    if let Some(backend) = args.backend_type {
        config.backend_type = backend;
    }

    match args.command {
        Some(Commands::PrintConfig) => {
            println!("{}", config.to_toml_string()?);
        }
        Some(Commands::ImportJournals { path }) => {
            backend::import_journals(&config, &path).await?;
        }
        Some(Commands::AssignPriority { priority }) => {
            backend::assign_priority(&config, priority).await?;
        }
        Some(Commands::Theme { command }) => {
            theme::handle_theme_command(&config, command).await?;
        }
        None => {
            // Run the TUI application
            app::run(&config).await?;
        }
    }

    Ok(())
}
EOF

