cat > /workspace/src/config.rs << 'EOF'
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use dirs::ProjectDirs;
use std::fs;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub backend_type: String,
    pub scroll_per_page: usize,
    pub sync_os_clipboard: bool,
    pub history_limit: usize,
    pub colored_tags: bool,
    pub datum_visibility: String,
    pub app_state_dir: PathBuf,

    #[serde(default)]
    pub export: ExportConfig,

    #[serde(default)]
    pub external_editor: EditorConfig,

    #[serde(default)]
    pub json_backend: BackendConfig,

    #[serde(default)]
    pub sqlite_backend: BackendConfig,

    #[serde(skip)]
    pub config_dir: PathBuf,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExportConfig {
    pub show_confirmation: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EditorConfig {
    pub auto_save: bool,
    pub temp_file_extension: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackendConfig {
    pub file_path: PathBuf,
}

impl Default for ExportConfig {
    fn default() -> Self {
        ExportConfig {
            show_confirmation: true,
        }
    }
}

impl Default for EditorConfig {
    fn default() -> Self {
        EditorConfig {
            auto_save: false,
            temp_file_extension: "txt".to_string(),
        }
    }
}

impl Default for BackendConfig {
    fn default() -> Self {
        let dirs = ProjectDirs::from("", "", "tui-journal").unwrap();
        BackendConfig {
            file_path: dirs.data_dir().join("entries.json"),
        }
    }
}

impl Config {
    pub fn load(config_path: &Option<PathBuf>) -> anyhow::Result<Self> {
        let config_dir = if let Some(path) = config_path {
            path.clone()
        } else {
            ProjectDirs::from("", "", "tui-journal")
                .ok_or_else(|| anyhow::anyhow!("Could not determine config directory"))?
                .config_dir()
                .to_path_buf()
        };

        // Ensure config directory exists
        fs::create_dir_all(&config_dir).ok();

        let config_file = config_dir.join("config.toml");

        let mut config = if config_file.exists() {
            let content = fs::read_to_string(&config_file)?;
            toml::from_str(&content).unwrap_or_else(|_| Self::default_config())
        } else {
            Self::default_config()
        };

        config.config_dir = config_dir;

        // Ensure state directory exists
        fs::create_dir_all(&config.app_state_dir).ok();

        Ok(config)
    }

    fn default_config() -> Self {
        let dirs = ProjectDirs::from("", "", "tui-journal").unwrap();
        Config {
            backend_type: "Sqlite".to_string(),
            scroll_per_page: 5,
            sync_os_clipboard: false,
            history_limit: 10,
            colored_tags: true,
            datum_visibility: "show".to_string(),
            app_state_dir: dirs
                .state_dir()
                .map(|p| p.to_path_buf())
                .unwrap_or_else(|| dirs.cache_dir().to_path_buf()),
            export: ExportConfig::default(),
            external_editor: EditorConfig::default(),
            json_backend: BackendConfig {
                file_path: dirs.data_dir().join("entries.json"),
            },
            sqlite_backend: BackendConfig {
                file_path: dirs.data_dir().join("entries.db"),
            },
            config_dir: dirs.config_dir().to_path_buf(),
        }
    }

    pub fn to_toml_string(&self) -> anyhow::Result<String> {
        let output = toml::to_string_pretty(self)?;
        Ok(output)
    }
}
EOF

