use crate::config::Config;
use crate::models::{JournalEntry, JournalFile};
use std::path::Path;
use std::fs;
use std::io;

pub async fn import_journals(config: &Config, source_path: &Path) -> anyhow::Result<()> {
    let import_data: JournalFile = serde_json::from_str(&fs::read_to_string(source_path)?)?;

    if config.backend_type.to_lowercase() == "sqlite" {
        // Import to SQLite
        import_to_sqlite(config, &import_data)?;
    } else {
        // Import to JSON
        import_to_json(config, &import_data)?;
    }

    Ok(())
}

fn import_to_json(config: &Config, data: &JournalFile) -> anyhow::Result<()> {
    let target_file = &config.json_backend.file_path;

    // Ensure parent directory exists
    if let Some(parent) = target_file.parent() {
        fs::create_dir_all(parent).ok();
    }

    let mut existing: JournalFile = if target_file.exists() {
        serde_json::from_str(&fs::read_to_string(target_file)?)?
    } else {
        JournalFile::new()
    };

    existing.entries.extend(data.entries.clone());
    let json = serde_json::to_string_pretty(&existing)?;
    fs::write(target_file, json)?;

    Ok(())
}

fn import_to_sqlite(config: &Config, data: &JournalFile) -> anyhow::Result<()> {
    let target_file = &config.sqlite_backend.file_path;

    // Ensure parent directory exists
    if let Some(parent) = target_file.parent() {
        fs::create_dir_all(parent).ok();
    }

    let conn = rusqlite::Connection::open(target_file)?;

    // Create tables if they don't exist
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS entries (
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            date TEXT NOT NULL,
            tags TEXT,
            priority INTEGER,
            created_at TEXT,
            updated_at TEXT
        )"
    )?;

    for entry in &data.entries {
        let tags_str = entry.tags.join(",");
        conn.execute(
            "INSERT OR REPLACE INTO entries (id, title, content, date, tags, priority, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            rusqlite::params![
                &entry.id,
                &entry.title,
                &entry.content,
                &entry.date,
                &tags_str,
                entry.priority,
                &entry.created_at,
                &entry.updated_at,
            ],
        )?;
    }

    Ok(())
}

pub async fn assign_priority(config: &Config, priority: u32) -> anyhow::Result<()> {
    if config.backend_type.to_lowercase() == "sqlite" {
        assign_priority_sqlite(config, priority)?;
    } else {
        assign_priority_json(config, priority)?;
    }

    Ok(())
}

fn assign_priority_json(config: &Config, priority: u32) -> anyhow::Result<()> {
    let target_file = &config.json_backend.file_path;

    if !target_file.exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "File not found").into());
    }

    let mut journal: JournalFile = serde_json::from_str(&fs::read_to_string(target_file)?)?;

    for entry in &mut journal.entries {
        if entry.priority.is_none() {
            entry.priority = Some(priority);
        }
    }

    let json = serde_json::to_string_pretty(&journal)?;
    fs::write(target_file, json)?;

    Ok(())
}

fn assign_priority_sqlite(config: &Config, priority: u32) -> anyhow::Result<()> {
    let target_file = &config.sqlite_backend.file_path;

    if !target_file.exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "File not found").into());
    }

    let conn = rusqlite::Connection::open(target_file)?;

    conn.execute(
        "UPDATE entries SET priority = ? WHERE priority IS NULL",
        rusqlite::params![priority],
    )?;

    Ok(())
}
