use crate::config::Config;
use crossterm::{
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{CrosstermBackend, Backend},
    Terminal,
};
use std::io;

pub async fn run(config: &Config) -> anyhow::Result<()> {
    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Run the app
    let _result = run_app(&mut terminal, config).await;

    // Restore terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen
    )?;
    terminal.show_cursor()?;

    Ok(())
}

async fn run_app<B: Backend>(
    terminal: &mut Terminal<B>,
    _config: &Config,
) -> anyhow::Result<()> {
    loop {
        terminal.draw(|f| {
            // Draw UI here
            let size = f.area();
            use ratatui::widgets::Block;
            use ratatui::text::Line;
            use ratatui::widgets::Paragraph;

            let block = Block::default().title("TUI Journal");
            let para = Paragraph::new(vec![
                Line::from("TUI Journal - Journal Management Application"),
                Line::from(""),
                Line::from("Press 'q' to quit"),
            ])
            .block(block);

            f.render_widget(para, size);
        })?;

        // Check for user input
        if let Ok(true) = crossterm::event::poll(std::time::Duration::from_millis(100)) {
            if let Ok(crossterm::event::Event::Key(key)) = crossterm::event::read() {
                match key.code {
                    crossterm::event::KeyCode::Char('q') => break,
                    _ => {}
                }
            }
        }
    }

    Ok(())
}
