    #[arg(short = 'c', long, value_name = "DIR PATH")]
    config: Option<PathBuf>,

    /// Increases logging verbosity each use for up to 3 times
    #[arg(short = 'v', long, action = clap::ArgAction::Count)]
    verbose: u8,

