fn get_home_dir() -> PathBuf {
    env::var_os("HOME")
        .and_then(|h| if h.is_empty() { None } else { Some(h) })
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/root"))
}

fn get_config_dir(override_config: Option<PathBuf>) -> PathBuf {
    if let Some(config) = override_config {
        return config;
    }

    let home = get_home_dir();
    home.join(".config/tui-journal")
}

fn get_backend_type(override_backend: Option<String>) -> String {
    override_backend.unwrap_or_else(|| "Sqlite".to_string())
}

fn get_json_file_path(override_json: Option<PathBuf>) -> PathBuf {
    if let Some(json) = override_json {
        return json;
    }

    let home = get_home_dir();
    home.join("tui-journal/entries.json")
}

fn get_sqlite_file_path(override_sqlite: Option<PathBuf>) -> PathBuf {
    if let Some(sqlite) = override_sqlite {
        return sqlite;
    }

    let home = get_home_dir();
    home.join("tui-journal/entries.db")
}

