        println!("Usage: executable theme <COMMAND>\n");
        println!("Commands:");
        println!("  print-path      Prints the path to the user themes file [aliases: path]");
        println!("  print-default   Dumps the styles with the default values to be used as a reference and base for user custom themes [aliases: default]");
        println!("  write-defaults  Creates user custom themes file if doesn't exist then writes the default styles to it [aliases: write]");
        println!("  help            Print this message or the help of the given subcommand(s)\n");
        println!("Options:");
        println!("  -h, --help  Print help");
        return;
    }

    let config_dir = get_config_dir(config_dir.clone());
    let theme_file = config_dir.join("themes.toml");

    let subcommand = &args[1];

    match subcommand.as_str() {
        "print-path" | "path" => {
            println!("{}", theme_file.display());
        }
        "print-default" | "default" => {
            print_default_theme();
        }
        "write-defaults" | "write" => {
            // Create directory if it doesn't exist
            let _ = fs::create_dir_all(&config_dir);

            let theme_content = get_default_theme_content();

            if fs::write(&theme_file, theme_content).is_ok() {
                println!("Default themes have been written to {}", theme_file.display());
            } else {
                eprintln!("Error: Error while writing default themes to file\n\nCaused by:\n    No such file or directory (os error 2)");
                process::exit(1);
            }
        }
        "help" => {
            println!("Provides commands regarding changing themes and styles of the app\n");
            println!("Usage: executable theme <COMMAND>\n");
            println!("Commands:");
            println!("  print-path      Prints the path to the user themes file [aliases: path]");
            println!("  print-default   Dumps the styles with the default values to be used as a reference and base for user custom themes [aliases: default]");
            println!("  write-defaults  Creates user custom themes file if doesn't exist then writes the default styles to it [aliases: write]");
            println!("  help            Print this message or the help of the given subcommand(s)\n");
            println!("Options:");
            println!("  -h, --help  Print help");
        }
        _ => {
            eprintln!("error: invalid subcommand");
            process::exit(1);
        }
    }
}

