fn parse_global_options(args: &[String]) -> (usize, Option<PathBuf>, Option<String>, Option<PathBuf>, Option<PathBuf>, u8, Option<PathBuf>) {
    let mut config_dir = None;
    let mut backend_type = None;
    let mut json_file = None;
    let mut sqlite_file = None;
    let mut verbose = 0;
    let mut log_file = None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config_dir = Some(PathBuf::from(&args[i + 1]));
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-j" | "--json-file-path" => {
                if i + 1 < args.len() {
                    json_file = Some(PathBuf::from(&args[i + 1]));
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-s" | "--sqlite-file-path" => {
                if i + 1 < args.len() {
                    sqlite_file = Some(PathBuf::from(&args[i + 1]));
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-b" | "--backend-type" => {
                if i + 1 < args.len() {
                    backend_type = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-v" | "--verbose" => {
                verbose += 1;
                i += 1;
            }
            "-l" | "--log" => {
                if i + 1 < args.len() {
                    log_file = Some(PathBuf::from(&args[i + 1]));
                    i += 2;
                } else {
                    i += 1;
                }
            }
            _ => {
                // This is our command
                return (i, config_dir, backend_type, json_file, sqlite_file, verbose, log_file);
            }
        }
    }

    (args.len(), config_dir, backend_type, json_file, sqlite_file, verbose, log_file)
}

fn print_help(program: &str) {
    println!("Tui app allows writing and managing journals/notes from within the terminal With different local back-ends\n");
    println!("Usage: {} [OPTIONS] [COMMAND]\n", program);
    println!("Commands:");
    println!("  print-config     Print the current settings including the paths for the back-end files [aliases: pc]");
    println!("  import-journals  Import journals from the given transfer JSON file to the current back-end file [aliases: imj]");
    println!("  assign-priority  Assign priority for all the entries with empty priority field [aliases: ap]");
    println!("  theme            Provides commands regarding changing themes and styles of the app [aliases: style]");
    println!("  help             Print this message or the help of the given subcommand(s)\n");
    println!("Options:");
    println!("  -j, --json-file-path <FILE PATH>    Sets the entries Json file path and starts using it");
    println!("  -s, --sqlite-file-path <FILE PATH>  Sets the entries sqlite file path and starts using it");
    println!("  -b, --backend-type <BACKEND_TYPE>   Sets the backend type and starts using it [possible values: json, sqlite]");
    println!("  -c, --config <DIR PATH>             Specifies the path for the configuration directory.");
    println!("                                      Configuration files is considered as root for themes file too.");
    println!("                                      It still accepts the path for configuration file for backward compatibility.");
    println!("                                      (default path: ~/.config/tui-journal)");
    println!("  -v, --verbose...                    Increases logging verbosity each use for up to 3 times");
    println!("  -l, --log <FILE PATH>               Specifies a file to use for logging");
    println!("                                      (default file: ~/.cache/tui-journal/tui-journal.log)");
    println!("  -h, --help                          Print help");
    println!("  -V, --version                       Print version");
}

fn get_home_dir() -> PathBuf {
    env::var_os("HOME")
        .and_then(|h| if h.is_empty() { None } else { Some(h) })
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/root"))
}

fn get_config_dir(override_config: Option<PathBuf>) -> PathBuf {
    if let Some(config) = override_config {
        return config;
    }

    let home = get_home_dir();
    home.join(".config/tui-journal")
}

fn get_backend_type(override_backend: Option<String>) -> String {
    override_backend.unwrap_or_else(|| "Sqlite".to_string())
}

fn get_json_file_path(override_json: Option<PathBuf>) -> PathBuf {
    if let Some(json) = override_json {
        return json;
    }

    let home = get_home_dir();
    home.join("tui-journal/entries.json")
}

fn get_sqlite_file_path(override_sqlite: Option<PathBuf>) -> PathBuf {
    if let Some(sqlite) = override_sqlite {
        return sqlite;
    }

    let home = get_home_dir();
    home.join("tui-journal/entries.db")
}

fn get_state_dir() -> PathBuf {
    let home = get_home_dir();
    home.join(".local/state/tui-journal")
}

fn handle_print_config(args: &[String], config_dir: Option<PathBuf>, backend_type: Option<String>, json_file: Option<PathBuf>, sqlite_file: Option<PathBuf>) {
    if args.len() > 1 && (args[1] == "-h" || args[1] == "--help") {
        println!("Print the current settings including the paths for the back-end files\n");
        println!("Usage: executable print-config\n");
